  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:
    """
    Transform the raw hurricane dataframe into analysis-ready dataframe.

    Produces standardized femininity score(s), log outcomes, a severity index, and basic cleaning.
    """
    # Make a copy to avoid modifying original
    df = df.copy()

    # Ensure numeric columns are numeric
    numeric_cols = ['masfem', 'masfem_mturk', 'gender_mf', 'alldeaths', 'ndam15', 'wind', 'min', 'category', 'year', 'elapsedyrs']
    for c in numeric_cols:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')

    # Drop rows missing primary IV or primary DVs and key severity controls
    required = []
    if 'masfem' in df.columns:
        required.append('masfem')
    required += [c for c in ['alldeaths', 'ndam15', 'wind', 'min', 'category'] if c in df.columns]
    if len(required) > 0:
        df = df.dropna(subset=required)

    # Create binary female name indicator from gender_mf (if present)
    if 'gender_mf' in df.columns:
        df['name_female'] = df['gender_mf'].astype(int)

    # Log-transform outcomes (add 1 to avoid log(0))
    if 'alldeaths' in df.columns:
        df['log_alldeaths'] = np.log(df['alldeaths'].fillna(0) + 1)
    if 'ndam15' in df.columns:
        df['log_ndam15'] = np.log(df['ndam15'].fillna(0) + 1)

    # Standardize masfem and masfem_mturk (z-scores)
    if 'masfem' in df.columns:
        df['z_masfem'] = (df['masfem'] - df['masfem'].mean()) / (df['masfem'].std(ddof=0) if df['masfem'].std(ddof=0) != 0 else 1.0)
    if 'masfem_mturk' in df.columns:
        df['z_masfem_mturk'] = (df['masfem_mturk'] - df['masfem_mturk'].mean()) / (df['masfem_mturk'].std(ddof=0) if df['masfem_mturk'].std(ddof=0) != 0 else 1.0)

    # Build a simple severity index combining wind (higher worse), category (higher worse) and pressure (lower worse)
    # Standardize components first (use population std to match z-score above)
    for comp in ['wind', 'category', 'min']:
        if comp in df.columns:
            df[f'z_{comp}'] = (df[comp] - df[comp].mean()) / (df[comp].std(ddof=0) if df[comp].std(ddof=0) != 0 else 1.0)

    # For pressure (min), lower pressure is more severe, so invert its z-score before combining
    if all(c in df.columns for c in ['wind', 'category', 'min']):
        df['severity_raw'] = df['z_wind'] + df['z_category'] + (-1.0 * df['z_min'])
        df['severity_z'] = (df['severity_raw'] - df['severity_raw'].mean()) / (df['severity_raw'].std(ddof=0) if df['severity_raw'].std(ddof=0) != 0 else 1.0)
    else:
        # If insufficient components, try to create severity_z from available standardized components
        comps = [c for c in ['z_wind', 'z_category', 'z_min'] if c in df.columns]
        if len(comps) > 0:
            # invert z_min if present
            arr = []
            for c in comps:
                if c == 'z_min':
                    arr.append(-1.0 * df[c])
                else:
                    arr.append(df[c])
            df['severity_raw'] = np.sum(arr, axis=0)
            df['severity_z'] = (df['severity_raw'] - df['severity_raw'].mean()) / (df['severity_raw'].std(ddof=0) if df['severity_raw'].std(ddof=0) != 0 else 1.0)

    # Keep only the columns useful for analysis (but preserve original numeric columns too)
    keep_cols = []
    for c in ['ind', 'year', 'name', 'masfem', 'z_masfem', 'masfem_mturk', 'z_masfem_mturk', 'gender_mf', 'name_female', 'alldeaths', 'log_alldeaths', 'ndam15', 'log_ndam15', 'wind', 'category', 'min', 'severity_z', 'elapsedyrs']:
        if c in df.columns:
            keep_cols.append(c)

    df = df[keep_cols].reset_index(drop=True)

    return df
